mapper.select:
SELECT device_id, binding_generation, property_code, desired_sequence, value_json::text AS value_json, converged_at FROM iot_desired_property WHERE device_id = #{deviceId} AND binding_generation = #{bindingGeneration}
AND property_code IN
#{propertyCode}
ORDER BY property_code

mapper.update:
UPDATE iot_device
SET desired_sequence = #{desiredSequence}
WHERE id = #{deviceId} AND desired_sequence = #{expectedDesiredSequence}

mapper.delete:
DELETE FROM iot_desired_property
WHERE device_id = #{deviceId} AND binding_generation = #{bindingGeneration}
  AND property_code = #{propertyCode}

mapper.select:
WITH reported(property_code, value_json) AS ( VALUES
(#{propertyCode}, CAST(#{valueJson} AS JSONB))
), converged AS ( UPDATE iot_desired_property AS desired SET converged_at = #{now} FROM reported WHERE desired.device_id = #{deviceId} AND desired.binding_generation = #{bindingGeneration} AND desired.property_code = reported.property_code AND desired.value_json = reported.value_json AND desired.converged_at IS NULL RETURNING desired.property_code ) SELECT converged.property_code, current_message.message_id FROM converged JOIN LATERAL ( SELECT message_id FROM iot_downlink_message WHERE device_id = #{deviceId} AND binding_generation = #{bindingGeneration} AND kind = 'DESIRED' AND target_code = converged.property_code AND status IN ('PENDING', 'SENDING', 'WAITING_ACK') ORDER BY desired_sequence DESC, message_id DESC LIMIT 1 ) AS current_message ON TRUE ORDER BY converged.property_code
